1	/**
2	 * Контракт между платформой и играми. Имена фиксированы: на них опираются все игры.
3	 * Игра импортирует из платформы только `platform/sdk/*`.
4	 */
5	
6	/** Генератор случайных чисел. `next()` возвращает число в [0, 1). Передаётся игре платформой. */
7	export interface Rng {
8	  next(): number;
9	}
10	
11	/**
12	 * Результат шага игры.
13	 * - `continue` — раунд продолжается, нужен следующий ход;
14	 * - `finished` — раунд окончен, `payout` — полная сумма к зачислению (0 при проигрыше).
15	 */
16	export type Step<S> =
17	  | { status: 'continue'; state: S }
18	  | { status: 'finished'; state: S; payout: number };
19	
20	/**
21	 * Серверный модуль игры. Платформа вызывает его внутри раунда: списывает ставку до `start`
22	 * и зачисляет `payout` после шага со статусом `finished`. Игра не знает о кошельке и балансе.
23	 *
24	 * Состояние `S` и параметры `P` должны сериализоваться в JSON: платформа хранит их на диске.
25	 */
26	export interface GameModule<P = any, S = any, A = any> {
27	  /** Идентификатор игры, совпадает с `id` в `manifest.json`. */
28	  id: string;
29	  /** Проверяет и нормализует параметры раунда. Бросает `GameError('INVALID_PARAMS')`. */
30	  validateParams(params: unknown): P;
31	  /** Начинает раунд (ставка уже списана). */
32	  start(ctx: { bet: number; params: P; rng: Rng }): Step<S>;
33	  /** Ход игрока. Бросает `GameError('INVALID_ACTION')` на недопустимое действие. */
34	  action(ctx: { bet: number; params: P; state: S; action: A; rng: Rng }): Step<S>;
35	  /** Что можно показать клиенту. До конца раунда (`finished = false`) скрытое не раскрывается. */
36	  publicView(state: S, finished: boolean): unknown;
37	}
38	
39	/** Ошибка игры с кодом (`INVALID_PARAMS`, `INVALID_ACTION`). Платформа передаёт код клиенту. */
40	export class GameError extends Error {
41	  /** Код ошибки. */
42	  code: string;
43	
44	  /**
45	   * @param code код ошибки, например `INVALID_PARAMS`
46	   * @param message необязательное пояснение для игрока
